package com.autoops.ai.tool.command;import com.autoops.ai.tool.AITool;import com.autoops.command.retrieval.CommandRetrievalService;import org.springframework.stereotype.Component;import java.util.Map;@Component public class SearchCommandsTool implements AITool{private final CommandRetrievalService search;public SearchCommandsTool(CommandRetrievalService s){search=s;}public String name(){return "search_commands";}public ToolRisk risk(){return ToolRisk.READ;}public Map<String,Object> schema(){return Map.of("type","object","properties",Map.of("query",Map.of("type","string")),"required",java.util.List.of("query"));}public Object execute(Map<String,Object>a,Long user){return search.search(String.valueOf(a.get("query")));}}
